# Fixture-independent native P07 regressions. Analytical controls are exact local
# limiting cases, never numerical values generated by the implementation.
const R = Fenix.Results
using SHA, Dates
result_settings(;changes...) = ode_settings(;changes...)
function result_error(f;category=nothing,path=nothing)
    error = try f(); nothing catch caught; caught end
    @test error isa R.ResultValidationError
    if error isa R.ResultValidationError
        category === nothing || @test error.category==category
        path === nothing || @test error.path==path
        @test !isempty(sprint(showerror,error))
    end
    error
end
function result_pair(;method="Tsit5",grid=(1.0,10.0),initial=0.5,observable_ids=("z","a"))
    d,e = compiler_pair(alpha=2.0,beta=0.0,initial=initial,observable_ids=observable_ids)
    e,R.run_experiment(e,result_settings(method=method,time_grid=grid))
end
function reload(record,experiment;manifest=R.to_dict(record.manifest),result=R.to_dict(record.result),trusted=nothing)
    bytes = Vector{UInt8}(codeunits(R._emit(result)))
    manifest["output"]["sha256"] = bytes2hex(sha256(bytes))
    R.from_json(R.RunRecord,R._emit(manifest),bytes;experiment,expected_manifest_sha256=trusted)
end
@testset "P07 native capture, immutable transport and normalized interfaces" begin
    for method in ("Tsit5","Rodas5P")
        e,record = result_pair(;method)
        m,r = R.to_dict(record.manifest),R.to_dict(record.result)
        @test record isa R.RunRecord
        @test isimmutable(record) && isimmutable(record.manifest) && isimmutable(record.result)
        @test r["observable_ids"] == ["a","z"]
        @test r["observable_state_ids"] == ["x","x"]
        @test record.result.times === (1.0,10.0)
        @test all(isapprox(x[1],2*t+0.5;atol=1e-9,rtol=1e-8) for (t,x) in zip(record.result.times,record.result.state_values))
        @test m["backend"]["solver"]["method"]==method
        @test m["backend"]["solver"]["options"]["maxiters"]==typemax(Int)
        @test m["backend"]["solver"]["options"]["jacobian"]=="exact_inplace"
        @test m["backend"]["solver"]["options"]["time_derivative"]=="autonomous_zero_inplace"
        @test keys(m["backend"]["evaluations"])==Set(["njev","nw"])
        @test m["evaluations"]["nfev"] > 0
        @test m["producer"]==Dict("name"=>"Fenix","version"=>string(pkgversion(Fenix)),"build_id"=>nothing)
        @test m["backend"]["environment"]["julia_version"]==string(VERSION)
        @test m["backend"]["environment"]["json_version"]==string(pkgversion(JSON))
        @test m["output"]["sha256"]==bytes2hex(sha256(record.result_bytes))
        @test m["fir"]["digest"]==Fenix.compile_experiment(e).digest==record.result.fir_digest
        @test occursin(r"\.[0-9]{3}000Z$",m["timing"]["started_at_utc"])
        loaded = R.from_json(R.RunRecord,R.to_json(record.manifest),record.result_bytes;experiment=e,
                            expected_manifest_sha256=bytes2hex(sha256(codeunits(R.to_json(record.manifest)))))
        @test R.to_json(loaded.manifest)==R.to_json(record.manifest)
        @test loaded.result_bytes==record.result_bytes
        @test isequal(R.to_dict(loaded.result),r)
        @test propertynames(loaded.result)==Tuple(Symbol(k) for k in keys(R.to_dict(loaded.result))) || Set(propertynames(loaded.result))==Set(Symbol.(keys(r)))
        @test_throws Exception setproperty!(loaded.result,:times,())
        @test_throws MethodError R.RunRecord()
        @test_throws MethodError R.RunManifest(m)
        @test_throws MethodError R.ODEResult(r)
        # Every exported mutable value and caller byte vector is isolated.
        input = record.result_bytes
        fresh = R.from_json(R.RunRecord,R.to_json(record.manifest),input;experiment=e)
        input[1]=0x00
        out = fresh.result_bytes
        out[1]=0xff
        @test fresh.result_bytes==record.result_bytes
        r["state_values"][1][1]=999.0
        @test R.to_dict(record.result)["state_values"][1][1] != 999.0
        m["backend"]["solver"]["options"]["save_start"]=true
        @test !R.to_dict(record.manifest)["backend"]["solver"]["options"]["save_start"]
    end
    for initial in (-0.0,nextfloat(0.0)), observable_ids in ((),("z","a"))
        e,record = result_pair(grid=(-0.0,),initial=initial,observable_ids=observable_ids)
        @test isequal(record.result.times,(-0.0,))
        @test isequal(record.result.state_values,((initial,),))
        @test R.to_dict(record.manifest)["integration"]=="skipped_zero_grid"
        @test R.to_dict(record.manifest)["evaluations"]["nfev"]==0
        @test length(record.result.observable_values[1])==length(observable_ids)
        @test isequal(reload(record,e).result.state_values,record.result.state_values)
    end
end
@testset "P07 raw bytes, checksums, portable integers and recorded observations" begin
    e,record = result_pair()
    m,r = R.to_dict(record.manifest),R.to_dict(record.result)
    # Deliberately noncanonical transport: formatting, key order and final newline.
    result_text = " \n"*R._emit(r)*"\n"
    m["output"]["sha256"] = bytes2hex(sha256(codeunits(result_text)))
    manifest_text = "\n "*R._emit(m)*" \n"
    loaded = R.from_json(R.RunRecord,Vector{UInt8}(codeunits(manifest_text)),Vector{UInt8}(codeunits(result_text));experiment=e)
    @test R.to_json(loaded.manifest)==manifest_text
    @test String(loaded.result_bytes)==result_text
    result_error(() -> R.from_json(R.RunRecord,manifest_text,record.result_bytes;experiment=e);category="CHECKSUM")
    result_error(() -> R.from_json(R.RunRecord,manifest_text,loaded.result_bytes;experiment=e,expected_manifest_sha256=repeat("0",64));category="CHECKSUM")
    for expected in ("",repeat("A",64),true,repeat("0",64)*"\n")
        result_error(() -> R.from_json(R.RunRecord,manifest_text,loaded.result_bytes;experiment=e,expected_manifest_sha256=expected))
    end
    huge = big(10)^100+3
    m = R.to_dict(record.manifest)
    m["execution"]["max_nfev"] = huge
    m["backend"]["solver"]["options"]["maxiters"] = huge
    m["backend"]["evaluations"]["njev"] = huge
    m["backend"]["evaluations"]["nw"] = huge
    m["producer"]["build_id"] = "observed:older-build 🧬"
    m["producer"]["version"] = "historical-version"
    m["backend"]["environment"]["julia_version"] = "historical-runtime"
    portable = reload(record,e;manifest=m)
    exported = R.to_dict(portable.manifest)
    @test exported["execution"]["max_nfev"]==huge
    @test exported["execution"]["max_nfev"] isa BigInt
    @test exported["backend"]["solver"]["options"]["maxiters"]==huge
    @test exported["backend"]["environment"]["julia_version"]=="historical-runtime"
    @test exported["producer"]["build_id"]=="observed:older-build 🧬"
    # Mutate GMP storage in one export and verify the immutable record remains intact.
    Base.GMP.MPZ.set!(exported["execution"]["max_nfev"],big(1))
    @test R.to_dict(portable.manifest)["execution"]["max_nfev"]==huge
    for value in (exported["backend"]["solver"]["options"]["maxiters"],
                  exported["backend"]["evaluations"]["njev"],exported["backend"]["evaluations"]["nw"])
        Base.GMP.MPZ.set!(value,big(2))
    end
    isolated = R.to_dict(portable.manifest)
    @test isolated["backend"]["solver"]["options"]["maxiters"]==huge
    @test isolated["backend"]["evaluations"]["njev"]==huge
    @test isolated["backend"]["evaluations"]["nw"]==huge
    function has_bigint(value)
        value isa BigInt && return true
        value isa R._Object && return any(has_bigint, value.entries)
        value isa Pair && return has_bigint(first(value)) || has_bigint(last(value))
        value isa Tuple && return any(has_bigint, value)
        false
    end
    @test !has_bigint(getfield(portable.manifest,:_data))
    for key in ("nfev", "njev", "nw", "maxiters", "max_nfev")
        text = R.to_json(portable.manifest)
        changed = replace(text,Regex("\\\""*key*"\\\":-?[0-9]+")=>"\""*key*"\":1e0")
        @test changed!=text
        result_error(() -> R.from_json(R.RunRecord,changed,portable.result_bytes;experiment=e);category="INTEGER")
    end
    # A Python payload is checked with Python-specific options/floor only.
    py = R.to_dict(record.manifest)
    py["backend"] = Dict{String,Any}("profile"=>"python-scipy-ode/0.1.0",
        "solver"=>Dict("name"=>"scipy.integrate.solve_ivp","method"=>"Radau","options"=>R._python_options("Radau")),
        "environment"=>Dict(k=>"recorded" for k in ("python_implementation","python_version","rfc8785_version","numpy_version","scipy_version")),
        "evaluations"=>Dict("njev"=>big(10)^100,"nlu"=>big(10)^100))
    @test R.to_dict(reload(record,e;manifest=py).manifest)["backend"]["evaluations"]["nlu"]==big(10)^100
    py["execution"]["rtol"]=1e-15
    result_error(() -> reload(record,e;manifest=py);category="EXECUTION_SPEC")
    jl = R.to_dict(record.manifest)
    jl["execution"]["rtol"]=1e-15
    @test reload(record,e;manifest=jl) isa R.RunRecord
end
@testset "P07 numerical token fidelity and malformed JSON" begin
    e,record = result_pair(grid=(1.0,),observable_ids=())
    base = R.to_dict(record.result)
    # Positive-time samples are preserved; loading does not recompute them.
    for (token,word) in (("-0","8000000000000000"),("5e-324","0000000000000001"),
        ("1.00000000000000011102230246251565404236316680908203125","3ff0000000000000"),
        ("1.00000000000000011102230246251565404236316680908203126","3ff0000000000001"))
        text = R._emit(base)
        text = replace(text,r"\"state_values\":\[\[[^\]]+\]\]"=>"\"state_values\":[["*token*"]]")
        m = R.to_dict(record.manifest)
        m["output"]["sha256"] = bytes2hex(sha256(codeunits(text)))
        parsed = R.from_json(R.RunRecord,R._emit(m),Vector{UInt8}(codeunits(text));experiment=e)
        @test string(reinterpret(UInt64,parsed.result.state_values[1][1]);base=16,pad=16)==word
    end
    for token in ("1e309","1e-400","-1e-400","true","\"1\"")
        text = replace(R._emit(base),r"\"state_values\":\[\[[^\]]+\]\]"=>"\"state_values\":[["*token*"]]")
        m = R.to_dict(record.manifest)
        m["output"]["sha256"] = bytes2hex(sha256(codeunits(text)))
        result_error(() -> R.from_json(R.RunRecord,R._emit(m),Vector{UInt8}(codeunits(text));experiment=e))
    end
    for raw in ("", "{} trailing", "{\"a\":1,}", "[1,]", "{\"a\":1,\"\\u0061\":2}", "{\"a\":\"\\ud800\"}","NaN","Infinity","\ufeff{}",String(UInt8[0xff]),"{\"a\":01}","{\"a\":1e}")
        result_error(() -> R.from_json(R.RunRecord,raw,record.result_bytes;experiment=e))
    end
end
@testset "P07 cross-artifact rejection, closed shapes and successful capture boundary" begin
    e,record = result_pair(grid=(0.0,1.0))
    original = R.to_dict(record.manifest)
    # Every present object member is required and every object level is closed.
    function closed_controls(node,path=())
        node isa AbstractDict || return
        for field in (collect(keys(node))...,"unknown")
            changed = deepcopy(original)
            target = changed
            for key in path
                target=target[key]
            end
            field=="unknown" ? (target[field]=true) : delete!(target,field)
            result_error(() -> R.from_json(R.RunRecord,R._emit(changed),record.result_bytes;experiment=e))
        end
        for (key,child) in node
            closed_controls(child,(path...,key))
        end
    end
    closed_controls(original)
    for (path,value) in ((("backend","profile"),"unknown"),(("schema_version",),"999"),
        (("backend","solver","method"),"DOP853"),(("backend","solver","options","jacobian"),"not_supplied"),
        (("backend","solver","options","save_start"),false),(("backend","evaluations","nw"),-1),
        (("evaluations","nfev"),0),(("execution","max_nfev"),1),(("producer","build_id"),""),
        (("timing","started_at_utc"),"2026-02-30T12:00:00.000000Z"),(("randomness","seed"),1))
        changed = deepcopy(original)
        target=changed
        for key in path[1:end-1]
            target=target[key]
        end
        target[last(path)]=value
        result_error(() -> reload(record,e;manifest=changed))
    end
    for (key,value) in (("state_ids",["wrong"]),("state_units",["mol"]),("observable_state_ids",["wrong","x"]),
        ("state_values",[[0.5]]),("state_values",[[1.0],[2.5]]),("observable_values",[[0.5,0.5],[9.0,9.0]]),
        ("times",[-0.0,1.0]))
        r=R.to_dict(record.result)
        r[key]=value
        result_error(() -> reload(record,e;result=r))
    end
    _,different = compiler_pair(alpha=2.0,beta=0.0,initial=0.5,volume=2e-15,observable_ids=("z","a"))
    @test Fenix.compile_experiment(different).digest==record.result.fir_digest
    result_error(() -> R.from_json(R.RunRecord,R.to_json(record.manifest),record.result_bytes;experiment=different);category="REFERENCE")
    @test_throws Fenix.Execution.ODEExecutionError R.run_experiment(e,result_settings(max_nfev=1))
    @test_throws FIRValidationError R.run_experiment(e,result_settings(profile="ssa"))
    # Observe clocks around verification/execution/checksum; wall time may move backward.
    times = [DateTime(2026,11,17,12),DateTime(2026,11,17,11)]
    monotonic = [UInt64(10),UInt64(1010)]
    calls = Ref(0)
    captured = R._capture(e,result_settings();wall=()->popfirst!(times),monotonic=()->popfirst!(monotonic),
        solve=(model,spec)->(calls[]+=1;Fenix.Execution.solve_ode(model,spec)))
    @test calls[]==1
    tm = R.to_dict(captured.manifest)["timing"]
    @test tm["finished_at_utc"] < tm["started_at_utc"]
    @test tm["elapsed_seconds"]==1e-6
    @test_throws ErrorException R._capture(e,result_settings();solve=(m,s)->error("solver failed"))
end
